const ORIGINAL_CODEX="//! Private continuation state for Codex remote control.\n\nuse std::fmt;\nuse std::fs;\nuse std::path::{Path, PathBuf};\n\nuse axum::body::{Body, Bytes};\nuse axum::extract::Request;\nuse axum::http::{HeaderMap, HeaderValue, Method, StatusCode};\nuse axum::response::Response;\nuse futures_util::StreamExt as _;\nuse serde::{Deserialize, Serialize};\nuse sha2::{Digest as _, Sha256};\n\nuse crate::app_state::AppState;\nuse crate::subscription::SubscriptionProvider;\n\npub const CONTINUATION_PREFIX: &crate::translation_core::Str = \"la_rc_\";\nconst FILE_NAME: &crate::translation_core::Str = \"codex-remote-control.lino\";\nconst STORE_VERSION: u32 = 1;\nconst MAX_RECORDS: usize = 1_000;\n\n#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]\npub struct EnrollmentIdentity {\n    pub principal_id: String,\n    pub account_name: String,\n    pub server_id: String,\n    pub environment_id: String,\n    pub installation_id: String,\n}\n\n#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]\npub struct EnrollmentRecord {\n    pub identity: EnrollmentIdentity,\n    pub upstream_token: String,\n    pub upstream_base_url: String,\n    pub expires_at: i64,\n}\n\n#[derive(Clone, Debug, Eq, PartialEq)]\npub struct BoundEnrollment {\n    pub token_hash: String,\n    pub record: EnrollmentRecord,\n}\n\n#[derive(Debug)]\npub enum StoreError {\n    Io(std::io::Error),\n    Decode(serde_json::Error),\n    Crypto(String),\n    Invalid,\n    StaleRotation,\n}\n\nimpl fmt::Display for StoreError {\n    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {\n        match self {\n            Self::Io(error) => write!(formatter, \"remote-control storage failed: {error}\"),\n            Self::Decode(error) => write!(formatter, \"remote-control state is invalid: {error}\"),\n            Self::Crypto(error) => {\n                write!(formatter, \"remote-control state cannot be opened: {error}\")\n            }\n            Self::Invalid => formatter.write_str(\"remote-control state is invalid\"),\n            Self::StaleRotation => {\n                formatter.write_str(\"remote-control enrollment changed during refresh\")\n            }\n        }\n    }\n}\n\nimpl std::error::Error for StoreError {}\n\nimpl From<std::io::Error> for StoreError {\n    fn from(error: std::io::Error) -> Self {\n        Self::Io(error)\n    }\n}\n\nimpl From<serde_json::Error> for StoreError {\n    fn from(error: serde_json::Error) -> Self {\n        Self::Decode(error)\n    }\n}\n\n#[derive(Debug, Serialize, Deserialize)]\nstruct StoredEnrollment {\n    token_hash: String,\n    sealed_record: String,\n}\n\n#[derive(Debug, Serialize, Deserialize)]\nstruct StoreFile {\n    version: u32,\n    records: Vec<StoredEnrollment>,\n}\n\n#[derive(Clone, Debug)]\npub struct CodexRemoteControlStore {\n    path: PathBuf,\n    lock_path: PathBuf,\n    token_secret: String,\n}\n\nimpl CodexRemoteControlStore {\n    pub fn open(data_dir: &Path, token_secret: &crate::translation_core::Str) -> crate::translation_core::Outcome<Self, StoreError> {\n        fs::create_dir_all(data_dir)?;\n        let path = data_dir.join(FILE_NAME);\n        let store = Self {\n            lock_path: path.with_extension(\"lock\"),\n            path,\n            token_secret: token_secret.to_string(),\n        };\n        crate::durable_file::with_exclusive_lock(&store.lock_path, || {\n            crate::durable_file::recover_transactional_write(&store.path)?;\n            let _ = store.load()?;\n            Ok::<_, StoreError>(())\n        })?;\n        Ok(store)\n    }\n\n    pub fn issue(&self, record: &EnrollmentRecord) -> crate::translation_core::Outcome<String, StoreError> {\n        validate_record(record)?;\n        crate::durable_file::with_exclusive_lock(&self.lock_path, || {\n            crate::durable_file::recover_transactional_write(&self.path)?;\n            let mut file = self.load()?;\n            self.remove_slot(&mut file, &record.identity)?;\n            let token = new_continuation();\n            file.records.push(self.seal(&token, record)?);\n            if file.records.len() > MAX_RECORDS {\n                file.records.remove(0);\n            }\n            self.flush(&file)?;\n            Ok(token)\n        })\n    }\n\n    pub fn resolve(&self, token: &crate::translation_core::Str, now: i64) -> crate::translation_core::Outcome<crate::translation_core::Maybe<EnrollmentRecord>, StoreError> {\n        let Some(hash) = continuation_hash(token) else {\n            return Ok(None);\n        };\n        crate::durable_file::with_exclusive_lock(&self.lock_path, || {\n            crate::durable_file::recover_transactional_write(&self.path)?;\n            let file = self.load()?;\n            let Some(stored) = file\n                .records\n                .iter()\n                .find(|stored| crate::token::constant_time_eq(&stored.token_hash, &hash))\n            else {\n                return Ok(None);\n            };\n            let record = self.unseal(stored)?;\n            Ok((record.expires_at > now).then_some(record))\n        })\n    }\n\n    pub fn find(\n        &self,\n        principal_id: &crate::translation_core::Str,\n        account_name: &crate::translation_core::Str,\n        server_id: &crate::translation_core::Str,\n        installation_id: &crate::translation_core::Str,\n    ) -> crate::translation_core::Outcome<crate::translation_core::Maybe<BoundEnrollment>, StoreError> {\n        crate::durable_file::with_exclusive_lock(&self.lock_path, || {\n            crate::durable_file::recover_transactional_write(&self.path)?;\n            let file = self.load()?;\n            for stored in &file.records {\n                let record = self.unseal(stored)?;\n                let identity = &record.identity;\n                if identity.principal_id == principal_id\n                    && identity.account_name == account_name\n                    && identity.server_id == server_id\n                    && identity.installation_id == installation_id\n                {\n                    return Ok(Some(BoundEnrollment {\n                        token_hash: stored.token_hash.clone(),\n                        record,\n                    }));\n                }\n            }\n            Ok(None)\n        })\n    }\n\n    pub fn rotate(\n        &self,\n        expected_token_hash: &crate::translation_core::Str,\n        record: &EnrollmentRecord,\n    ) -> crate::translation_core::Outcome<String, StoreError> {\n        validate_record(record)?;\n        crate::durable_file::with_exclusive_lock(&self.lock_path, || {\n            crate::durable_file::recover_transactional_write(&self.path)?;\n            let mut file = self.load()?;\n            let Some(index) = file.records.iter().position(|stored| {\n                crate::token::constant_time_eq(&stored.token_hash, expected_token_hash)\n            }) else {\n                return Err(StoreError::StaleRotation);\n            };\n            if self.unseal(&file.records[index])?.identity != record.identity {\n                return Err(StoreError::StaleRotation);\n            }\n            let token = new_continuation();\n            file.records[index] = self.seal(&token, record)?;\n            self.flush(&file)?;\n            Ok(token)\n        })\n    }\n\n    pub fn owns_environment(\n        &self,\n        principal_id: &crate::translation_core::Str,\n        account_name: &crate::translation_core::Str,\n        environment_id: &crate::translation_core::Str,\n    ) -> crate::translation_core::Outcome<bool, StoreError> {\n        crate::durable_file::with_exclusive_lock(&self.lock_path, || {\n            crate::durable_file::recover_transactional_write(&self.path)?;\n            let file = self.load()?;\n            for stored in &file.records {\n                let identity = self.unseal(stored)?.identity;\n                if identity.principal_id == principal_id\n                    && identity.account_name == account_name\n                    && identity.environment_id == environment_id\n                {\n                    return Ok(true);\n                }\n            }\n            Ok(false)\n        })\n    }\n\n    fn remove_slot(\n        &self,\n        file: &mut StoreFile,\n        identity: &EnrollmentIdentity,\n    ) -> Result<(), StoreError> {\n        let mut kept = Vec::with_capacity(file.records.len());\n        for stored in file.records.drain(..) {\n            let current = self.unseal(&stored)?.identity;\n            if current.principal_id != identity.principal_id\n                || current.account_name != identity.account_name\n                || current.installation_id != identity.installation_id\n            {\n                kept.push(stored);\n            }\n        }\n        file.records = kept;\n        Ok(())\n    }\n\n    fn seal(&self, token: &crate::translation_core::Str, record: &EnrollmentRecord) -> crate::translation_core::Outcome<StoredEnrollment, StoreError> {\n        let plaintext = serde_json::to_string(record)?;\n        let sealed_record = crate::providers::seal_secret(&plaintext, &self.token_secret)\n            .map_err(|error| StoreError::Crypto(error.to_string()))?;\n        Ok(StoredEnrollment {\n            token_hash: continuation_hash(token).ok_or(StoreError::Invalid)?,\n            sealed_record,\n        })\n    }\n\n    fn unseal(&self, stored: &StoredEnrollment) -> crate::translation_core::Outcome<EnrollmentRecord, StoreError> {\n        let plaintext = crate::providers::open_secret(&stored.sealed_record, &self.token_secret)\n            .map_err(|error| StoreError::Crypto(error.to_string()))?;\n        let record = serde_json::from_str(&plaintext)?;\n        validate_record(&record)?;\n        Ok(record)\n    }\n\n    fn load(&self) -> crate::translation_core::Outcome<StoreFile, StoreError> {\n        if !self.path.exists() {\n            return Ok(StoreFile {\n                version: STORE_VERSION,\n                records: Vec::new(),\n            });\n        }\n        let file: StoreFile = crate::lino_json::decode(&fs::read_to_string(&self.path)?)?;\n        if file.version != STORE_VERSION {\n            return Err(StoreError::Invalid);\n        }\n        Ok(file)\n    }\n\n    fn flush(&self, file: &StoreFile) -> crate::translation_core::Outcome<(), StoreError> {\n        let encoded = crate::lino_json::encode(file)?;\n        crate::durable_file::transactional_write_owner_only(&self.path, encoded.as_bytes())?;\n        Ok(())\n    }\n}\n\nfn new_continuation() -> String {\n    format!(\n        \"{CONTINUATION_PREFIX}{}{}\",\n        uuid::Uuid::new_v4().simple(),\n        uuid::Uuid::new_v4().simple()\n    )\n}\n\nfn continuation_hash(token: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {\n    token.strip_prefix(CONTINUATION_PREFIX)?;\n    Some(hex::encode(Sha256::digest(token.as_bytes())))\n}\n\nfn validate_record(record: &EnrollmentRecord) -> crate::translation_core::Outcome<(), StoreError> {\n    let identity = &record.identity;\n    let values = [\n        identity.principal_id.as_str(),\n        identity.account_name.as_str(),\n        identity.server_id.as_str(),\n        identity.environment_id.as_str(),\n        identity.installation_id.as_str(),\n        record.upstream_token.as_str(),\n        record.upstream_base_url.as_str(),\n    ];\n    if values\n        .iter()\n        .any(|value| value.is_empty() || value.len() > 8_192)\n        || record.expires_at <= 0\n    {\n        return Err(StoreError::Invalid);\n    }\n    Ok(())\n}\n\nconst ROOT: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/\";\nconst SERVER: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/server\";\nconst ENROLL: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/server/enroll\";\nconst REFRESH: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/server/refresh\";\nconst REFRESH_UPSTREAM: &crate::translation_core::Str = \"/wham/remote/control/server/refresh\";\nconst PAIR: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/server/pair\";\nconst PAIR_STATUS: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/server/pair/status\";\nconst ENVIRONMENTS: &crate::translation_core::Str = \"/api/services/codex/backend-api/wham/remote/control/environments/\";\n\n#[derive(Debug, Eq, PartialEq)]\nenum Operation {\n    WebSocket,\n    Enroll,\n    Refresh,\n    Pair,\n    PairStatus,\n    List { environment_id: String },\n    Revoke { environment_id: String },\n}\n\npub fn is_remote_control_path(path: &crate::translation_core::Str) -> bool {\n    path.starts_with(ROOT)\n}\n\nfn operation(method: &Method, path: &crate::translation_core::Str) -> crate::translation_core::Maybe<Operation> {\n    match (method, path) {\n        (&Method::GET, SERVER) => Some(Operation::WebSocket),\n        (&Method::POST, ENROLL) => Some(Operation::Enroll),\n        (&Method::POST, REFRESH) => Some(Operation::Refresh),\n        (&Method::POST, PAIR) => Some(Operation::Pair),\n        (&Method::POST, PAIR_STATUS) => Some(Operation::PairStatus),\n        _ => dynamic_operation(method, path),\n    }\n}\n\n/// Whether the route authenticates a Router-issued continuation itself.\n///\n/// The ordinary inference middleware cannot validate `la_rc_` credentials;\n/// these handlers resolve their encrypted, identity-bound state before ever\n/// reading a request body.\npub fn authenticates_continuation(method: &Method, path: &crate::translation_core::Str) -> bool {\n    matches!(\n        operation(method, path),\n        Some(Operation::WebSocket | Operation::Pair | Operation::PairStatus)\n    )\n}\n\nfn dynamic_operation(method: &Method, path: &crate::translation_core::Str) -> crate::translation_core::Maybe<Operation> {\n    let tail = path.strip_prefix(ENVIRONMENTS)?;\n    let segments = tail.split('/').collect::<Vec<_>>();\n    match (method, segments.as_slice()) {\n        (&Method::GET, [environment, \"clients\"]) => Some(Operation::List {\n            environment_id: decode_path_segment(environment)?,\n        }),\n        (&Method::DELETE, [environment, \"clients\", client])\n            if decode_path_segment(client).is_some() =>\n        {\n            Some(Operation::Revoke {\n                environment_id: decode_path_segment(environment)?,\n            })\n        }\n        _ => None,\n    }\n}\n\npub async fn forward(state: AppState, request: Request) -> Response {\n    let method = request.method().clone();\n    let uri = request.uri().clone();\n    let Some(operation) = operation(&method, uri.path()) else {\n        return api_error(StatusCode::NOT_FOUND, \"not_found_error\", \"route not found\");\n    };\n    match operation {\n        Operation::Pair | Operation::PairStatus | Operation::WebSocket => {\n            Box::pin(continuation_request(state, request, operation)).await\n        }\n        Operation::Enroll\n        | Operation::Refresh\n        | Operation::List { .. }\n        | Operation::Revoke { .. } => primary_request(state, request, operation).await,\n    }\n}\n\nasync fn primary_request(state: AppState, request: Request, operation: Operation) -> Response {\n    let method = request.method().clone();\n    let uri = request.uri().clone();\n    let headers = request.headers().clone();\n    let Some(primary) = bearer(&headers) else {\n        return authentication_error(\"Codex remote control requires Router authentication\");\n    };\n    if !crate::proxy::codex_carrier_accepted(&state, Some(primary)) {\n        return authentication_error(\n            \"Codex remote-control enrollment requires the paired Router-issued at- token\",\n        );\n    }\n    let claims = match crate::proxy::authenticate_client_error(&state, &headers) {\n        Ok(claims) => claims,\n        Err(error) => return error.render(crate::api_error::ApiDialect::OpenAi),\n    };\n    let Ok((client, principal)) = crate::client_policy::bound_client(&claims) else {\n        return permission_error(\"Codex remote control requires a managed Codex client token\");\n    };\n    if client != crate::clients::ClientKind::Codex {\n        return permission_error(\"Codex remote control requires a managed Codex client token\");\n    }\n    let principal = principal.to_string();\n    let Ok(body) = axum::body::to_bytes(request.into_body(), state.max_proxy_request_bytes).await\n    else {\n        return api_error(\n            StatusCode::PAYLOAD_TOO_LARGE,\n            \"invalid_request_error\",\n            \"request body exceeds the remote-control proxy limit\",\n        );\n    };\n    let selected = match crate::native_service::selected_subscription(\n        &state,\n        &headers,\n        &claims,\n        SubscriptionProvider::Codex,\n        Some(&body),\n    )\n    .await\n    {\n        Ok(selected) => selected,\n        Err(response) => return response,\n    };\n    let root = codex_backend_root(&state, &selected);\n    let target = primary_target(&state, &headers, &selected, &service_uri(&uri));\n\n    match operation {\n        Operation::Enroll => {\n            enroll(state, claims, principal, selected.name, root, body, target).await\n        }\n        Operation::Refresh => refresh(state, principal, selected.name, root, body, target).await,\n        Operation::List { environment_id } | Operation::Revoke { environment_id } => {\n            match state\n                .provider_store\n                .codex_remote_control()\n                .owns_environment(&principal, &selected.name, &environment_id)\n            {\n                Ok(true) => crate::native_service::relay_http(&state, &method, body, target).await,\n                Ok(false) => permission_error(\n                    \"the remote-control environment is not owned by this Router principal\",\n                ),\n                Err(_) => unavailable(\"remote-control ownership state is unavailable\"),\n            }\n        }\n        Operation::Pair | Operation::PairStatus | Operation::WebSocket => unreachable!(),\n    }\n}\n\nfn service_uri(uri: &axum::http::Uri) -> String {\n    let path = uri\n        .path()\n        .strip_prefix(\"/api/services/codex/backend-api\")\n        .unwrap_or_else(|| uri.path());\n    uri_path_and_query(path, uri.query().unwrap_or_default())\n}\n\nfn uri_path_and_query(path: &crate::translation_core::Str, query: &crate::translation_core::Str) -> String {\n    if query.is_empty() {\n        path.to_string()\n    } else {\n        format!(\"{path}?{query}\")\n    }\n}\n\nfn codex_backend_root(\n    state: &AppState,\n    selected: &crate::accounts::SelectedSubscriptionAccount,\n) -> String {\n    let base = state\n        .subscription_base_url\n        .clone()\n        .unwrap_or_else(|| selected.token.base_url(SubscriptionProvider::Codex));\n    base.strip_suffix(\"/codex\")\n        .unwrap_or(&base)\n        .trim_end_matches('/')\n        .to_string()\n}\n\nfn primary_target(\n    state: &AppState,\n    incoming: &HeaderMap,\n    selected: &crate::accounts::SelectedSubscriptionAccount,\n    uri: &crate::translation_core::Str,\n) -> crate::native_service::Target {\n    let root = codex_backend_root(state, selected);\n    let mut headers = crate::proxy::native_request_headers(incoming, &selected.token.access_token);\n    if let Some(account_id) = selected.token.account_id.as_deref()\n        && let Ok(value) = HeaderValue::from_str(account_id)\n    {\n        headers.insert(\"chatgpt-account-id\", value);\n    }\n    crate::native_service::Target {\n        client: crate::upstream_client::subscription_client(\n            &state.client,\n            SubscriptionProvider::Codex,\n            state.subscription_base_url.is_some(),\n        )\n        .clone(),\n        url: format!(\"{root}{uri}\"),\n        headers,\n    }\n}\n\nasync fn enroll(\n    state: AppState,\n    claims: crate::token::TokenClaims,\n    principal: String,\n    account_name: String,\n    upstream_root: String,\n    body: Bytes,\n    target: crate::native_service::Target,\n) -> Response {\n    let Some(installation_id) = json_string(&body, \"installation_id\") else {\n        return invalid_request(\"remote-control enrollment requires installation_id\");\n    };\n    let response = match send_buffered(&state, Method::POST, body, target).await {\n        Ok(response) => response,\n        Err(response) => return response,\n    };\n    if !response.status.is_success() {\n        return response.into_response();\n    }\n    let (mut json, server_id, environment_id, upstream_token, expires_at) =\n        match enrollment_response(&response.body) {\n            Ok(parsed) => parsed,\n            Err(response) => return response,\n        };\n    let record = EnrollmentRecord {\n        identity: EnrollmentIdentity {\n            principal_id: principal,\n            account_name,\n            server_id,\n            environment_id,\n            installation_id,\n        },\n        upstream_token,\n        upstream_base_url: upstream_root,\n        expires_at,\n    };\n    let Ok(continuation) = state.provider_store.codex_remote_control().issue(&record) else {\n        return unavailable(\"remote-control continuation state could not be stored\");\n    };\n    json[\"remote_control_token\"] = crate::translation_core::Json::String(continuation);\n    crate::audit::record_control_plane_request(\n        &state,\n        &claims,\n        \"codex\",\n        \"codex.remote_control.enroll\",\n    );\n    response.with_json(&json)\n}\n\nasync fn refresh(\n    state: AppState,\n    principal: String,\n    account_name: String,\n    upstream_root: String,\n    body: Bytes,\n    mut target: crate::native_service::Target,\n) -> Response {\n    let Some(server_id) = json_string(&body, \"server_id\") else {\n        return invalid_request(\"remote-control refresh requires server_id\");\n    };\n    let Some(installation_id) = json_string(&body, \"installation_id\") else {\n        return invalid_request(\"remote-control refresh requires installation_id\");\n    };\n    let current = match state.provider_store.codex_remote_control().find(\n        &principal,\n        &account_name,\n        &server_id,\n        &installation_id,\n    ) {\n        Ok(Some(current)) => current,\n        Ok(None) => {\n            return permission_error(\n                \"the remote-control enrollment is not owned by this Router principal\",\n            );\n        }\n        Err(_) => return unavailable(\"remote-control continuation state is unavailable\"),\n    };\n    target.url = format!(\"{}{REFRESH_UPSTREAM}\", current.record.upstream_base_url);\n    let response = match send_buffered(&state, Method::POST, body, target).await {\n        Ok(response) => response,\n        Err(response) => return response,\n    };\n    if !response.status.is_success() {\n        return response.into_response();\n    }\n    let (mut json, returned_server, returned_environment, upstream_token, expires_at) =\n        match enrollment_response(&response.body) {\n            Ok(parsed) => parsed,\n            Err(response) => return response,\n        };\n    if returned_server != current.record.identity.server_id\n        || returned_environment != current.record.identity.environment_id\n        || upstream_root != current.record.upstream_base_url\n    {\n        return unavailable(\"remote-control refresh returned inconsistent enrollment identity\");\n    }\n    let record = EnrollmentRecord {\n        identity: current.record.identity,\n        upstream_token,\n        upstream_base_url: current.record.upstream_base_url,\n        expires_at,\n    };\n    let continuation = match state\n        .provider_store\n        .codex_remote_control()\n        .rotate(&current.token_hash, &record)\n    {\n        Ok(token) => token,\n        Err(StoreError::StaleRotation) => {\n            return unavailable(\"remote-control enrollment changed during refresh\");\n        }\n        Err(_) => return unavailable(\"remote-control continuation state could not be stored\"),\n    };\n    json[\"remote_control_token\"] = serde_json::Value::String(continuation);\n    response.with_json(&json)\n}\n\nasync fn continuation_request(state: AppState, request: Request, operation: Operation) -> Response {\n    let headers = request.headers().clone();\n    let Some(token) = bearer(&headers).filter(|token| token.starts_with(CONTINUATION_PREFIX))\n    else {\n        return authentication_error(\"a valid Router remote-control continuation is required\");\n    };\n    let record = match state\n        .provider_store\n        .codex_remote_control()\n        .resolve(token, crate::operation_context::now().timestamp())\n    {\n        Ok(Some(record)) => record,\n        Ok(None) => {\n            return authentication_error(\"the remote-control continuation is invalid or expired\");\n        }\n        Err(_) => return unavailable(\"remote-control continuation state is unavailable\"),\n    };\n    if operation == Operation::WebSocket && !websocket_identity_matches(&headers, &record.identity)\n    {\n        return permission_error(\"the remote-control connection does not match this enrollment\");\n    }\n    let uri = request.uri().clone();\n    let target = continuation_target(&state, &headers, &record, &uri);\n    if operation == Operation::WebSocket {\n        if !is_websocket(&headers) {\n            return invalid_request(\n                \"the remote-control server endpoint requires a WebSocket upgrade\",\n            );\n        }\n        return crate::native_service::upgrade_websocket(state, request, target, None).await;\n    }\n    let Ok(body) = axum::body::to_bytes(request.into_body(), state.max_proxy_request_bytes).await\n    else {\n        return api_error(\n            StatusCode::PAYLOAD_TOO_LARGE,\n            \"invalid_request_error\",\n            \"request body exceeds the remote-control proxy limit\",\n        );\n    };\n    if operation == Operation::Pair {\n        let response = match send_buffered(&state, Method::POST, body, target).await {\n            Ok(response) => response,\n            Err(response) => return response,\n        };\n        if response.status.is_success() && !pair_identity_matches(&response.body, &record.identity)\n        {\n            return unavailable(\"remote-control pairing returned inconsistent enrollment identity\");\n        }\n        return response.into_response();\n    }\n    crate::native_service::relay_http(&state, &Method::POST, body, target).await\n}\n\nfn continuation_target(\n    state: &AppState,\n    incoming: &HeaderMap,\n    record: &EnrollmentRecord,\n    uri: &axum::http::Uri,\n) -> crate::native_service::Target {\n    let path = uri\n        .path()\n        .strip_prefix(\"/api/services/codex/backend-api\")\n        .unwrap_or_else(|| uri.path());\n    let path = uri_path_and_query(path, uri.query().unwrap_or_default());\n    crate::native_service::Target {\n        client: crate::upstream_client::subscription_client(\n            &state.client,\n            SubscriptionProvider::Codex,\n            state.subscription_base_url.is_some(),\n        )\n        .clone(),\n        url: format!(\"{}{path}\", record.upstream_base_url),\n        headers: crate::proxy::native_request_headers(incoming, &record.upstream_token),\n    }\n}\n\nstruct BufferedResponse {\n    status: StatusCode,\n    headers: HeaderMap,\n    body: Bytes,\n}\n\nimpl BufferedResponse {\n    fn into_response(self) -> Response {\n        let mut response = Response::new(Body::from(self.body));\n        *response.status_mut() = self.status;\n        *response.headers_mut() = self.headers;\n        response\n    }\n\n    fn with_json(self, json: &crate::translation_core::Json) -> Response {\n        let mut response = Response::new(Body::from(json.to_string()));\n        *response.status_mut() = self.status;\n        *response.headers_mut() = self.headers;\n        response\n    }\n}\n\nasync fn send_buffered(\n    state: &AppState,\n    method: Method,\n    body: Bytes,\n    target: crate::native_service::Target,\n) -> crate::translation_core::Outcome<BufferedResponse, Response> {\n    let upstream = target\n        .client\n        .request(\n            reqwest::Method::from_bytes(method.as_str().as_bytes()).expect(\"valid HTTP method\"),\n            target.url,\n        )\n        .headers(target.headers)\n        .body(body.clone())\n        .send()\n        .await\n        .map_err(|_| unavailable(\"remote-control upstream request failed\"))?;\n    let status = StatusCode::from_u16(upstream.status().as_u16())\n        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);\n    let headers = crate::proxy::relay_response_headers(upstream.headers());\n    let mut stream = upstream.bytes_stream();\n    let mut response_body = Vec::new();\n    while let Some(chunk) = stream.next().await {\n        let chunk = chunk.map_err(|_| unavailable(\"remote-control upstream response failed\"))?;\n        if response_body.len().saturating_add(chunk.len()) > state.max_proxy_request_bytes {\n            return Err(unavailable(\n                \"remote-control upstream response exceeds the proxy limit\",\n            ));\n        }\n        response_body.extend_from_slice(&chunk);\n    }\n    state\n        .metrics\n        .record_bytes(body.len() as u64, response_body.len() as u64);\n    Ok(BufferedResponse {\n        status,\n        headers,\n        body: Bytes::from(response_body),\n    })\n}\n\nfn enrollment_response(\n    body: &[u8],\n) -> crate::translation_core::Outcome<(crate::translation_core::Json, String, String, String, i64), Response> {\n    let json: serde_json::Value = serde_json::from_slice(body)\n        .map_err(|_| unavailable(\"remote-control enrollment response is malformed\"))?;\n    let string = |name| {\n        json.get(name)\n            .and_then(crate::translation_core::Json::as_str)\n            .filter(|value| !value.is_empty())\n            .map(str::to_string)\n            .ok_or_else(|| unavailable(\"remote-control enrollment response is malformed\"))\n    };\n    let server_id = string(\"server_id\")?;\n    let environment_id = string(\"environment_id\")?;\n    let upstream_token = string(\"remote_control_token\")?;\n    let expires = string(\"expires_at\")?;\n    let expires_at = chrono::DateTime::parse_from_rfc3339(&expires)\n        .map_err(|_| unavailable(\"remote-control enrollment response has an invalid expiry\"))?\n        .timestamp();\n    if expires_at <= crate::operation_context::now().timestamp() {\n        return Err(unavailable(\n            \"remote-control enrollment response is already expired\",\n        ));\n    }\n    Ok((json, server_id, environment_id, upstream_token, expires_at))\n}\n\nfn json_string(body: &[u8], name: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {\n    serde_json::from_slice::<serde_json::Value>(body)\n        .ok()?\n        .get(name)?\n        .as_str()\n        .filter(|value| !value.is_empty())\n        .map(str::to_string)\n}\n\nfn pair_identity_matches(body: &[u8], identity: &EnrollmentIdentity) -> bool {\n    let Ok(json) = serde_json::from_slice::<serde_json::Value>(body) else {\n        return false;\n    };\n    json.get(\"server_id\").and_then(crate::translation_core::Json::as_str) == Some(identity.server_id.as_str())\n        && json\n            .get(\"environment_id\")\n            .and_then(crate::translation_core::Json::as_str)\n            == Some(identity.environment_id.as_str())\n}\n\nfn websocket_identity_matches(headers: &HeaderMap, identity: &EnrollmentIdentity) -> bool {\n    header(headers, \"x-codex-server-id\") == crate::translation_core::Maybe::Some(identity.server_id.as_str())\n        && header(headers, \"x-codex-installation-id\") == crate::translation_core::Maybe::Some(identity.installation_id.as_str())\n}\n\nfn header<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {\n    let mut values = headers.get_all(name).iter();\n    let value = values.next()?.to_str().ok()?;\n    values.next().is_none().then_some(value)\n}\n\nfn bearer(headers: &HeaderMap) -> crate::translation_core::Maybe<&crate::translation_core::Str> {\n    let value = header(headers, \"authorization\")?;\n    let (scheme, token) = value.split_once(' ')?;\n    (scheme.eq_ignore_ascii_case(\"bearer\") && !token.is_empty()).then_some(token)\n}\n\nfn is_websocket(headers: &HeaderMap) -> bool {\n    header(headers, \"upgrade\").is_some_and(|value| value.eq_ignore_ascii_case(\"websocket\"))\n}\n\nfn decode_path_segment(segment: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {\n    if segment.is_empty() {\n        return None;\n    }\n    let bytes = segment.as_bytes();\n    let mut decoded = Vec::with_capacity(bytes.len());\n    let mut index = 0;\n    while index < bytes.len() {\n        if bytes[index] == b'%' {\n            let high = hex_digit(*bytes.get(index + 1)?)?;\n            let low = hex_digit(*bytes.get(index + 2)?)?;\n            decoded.push((high << 4) | low);\n            index += 3;\n        } else {\n            decoded.push(bytes[index]);\n            index += 1;\n        }\n    }\n    String::from_utf8(decoded)\n        .ok()\n        .filter(|value| !value.chars().any(char::is_control))\n}\n\nconst fn hex_digit(byte: u8) -> crate::translation_core::Maybe<u8> {\n    match byte {\n        b'0'..=b'9' => Some(byte - b'0'),\n        b'a'..=b'f' => Some(byte - b'a' + 10),\n        b'A'..=b'F' => Some(byte - b'A' + 10),\n        _ => None,\n    }\n}\n\nfn invalid_request(message: &crate::translation_core::Str) -> Response {\n    api_error(StatusCode::BAD_REQUEST, \"invalid_request_error\", message)\n}\n\nfn authentication_error(message: &crate::translation_core::Str) -> Response {\n    api_error(StatusCode::UNAUTHORIZED, \"authentication_error\", message)\n}\n\nfn permission_error(message: &crate::translation_core::Str) -> Response {\n    api_error(StatusCode::FORBIDDEN, \"permission_error\", message)\n}\n\nfn unavailable(message: &crate::translation_core::Str) -> Response {\n    api_error(StatusCode::SERVICE_UNAVAILABLE, \"api_error\", message)\n}\n\nfn api_error(status: StatusCode, error_type: &crate::translation_core::Str, message: &crate::translation_core::Str) -> Response {\n    crate::api_error::PresentedError {\n        status,\n        error_type,\n        message,\n    }\n    .render(crate::api_error::ApiDialect::OpenAi)\n}\n";
const ORIGINAL_CONVERSATIONS="//! Authenticated native `OpenAI` Conversations and conversation-items lifecycle.\n\nuse axum::body::{Body, Bytes};\nuse axum::extract::{OriginalUri, Path, Request, State};\nuse axum::http::{HeaderMap, Method, StatusCode, Uri};\nuse axum::response::{IntoResponse, Response};\nuse futures_util::StreamExt;\n\nuse crate::app_state::AppState;\nuse crate::response_affinity::{\n    AffinityDestination, ResponseAffinity, ResponseNamespace, ResponseOwner,\n};\n\nstruct Forwarded {\n    status: StatusCode,\n    headers: HeaderMap,\n    body: Bytes,\n}\n\npub async fn create(\n    State(state): State<AppState>,\n    OriginalUri(uri): OriginalUri,\n    request: Request,\n) -> Response {\n    let (claims, owner) = match authenticate(&state, request.headers()) {\n        Ok(authenticated) => authenticated,\n        Err(response) => return response,\n    };\n    let Some((conversation_namespace, _)) = ResponseNamespace::conversations_from_path(uri.path())\n    else {\n        return conversation_not_found();\n    };\n    if conversation_namespace == ResponseNamespace::QwenConversations {\n        return unsupported();\n    }\n    let destination = match crate::resource_capture::destination_for_claims(&state, &claims).await {\n        Ok(destination) if destination_matches(conversation_namespace, &destination) => destination,\n        Ok(_) => return unsupported(),\n        Err(response) => return response,\n    };\n    let (parts, body) = request.into_parts();\n    let body = match bounded_request_body(&state, body).await {\n        Ok(body) => body,\n        Err(response) => return response,\n    };\n    let upstream_path = with_query(\"/v1/conversations\", &uri);\n    let forwarded = match forward(\n        &state,\n        &claims,\n        &parts.method,\n        &parts.headers,\n        &body,\n        uri.path(),\n        &upstream_path,\n        &destination,\n    )\n    .await\n    {\n        Ok(forwarded) => forwarded,\n        Err(response) => return response,\n    };\n    if forwarded.status.is_success() {\n        let Some(conversation_id) = root_id(&forwarded.body) else {\n            return upstream_error(\"conversation create response did not contain an id\");\n        };\n        if let Err(error) = state.provider_store.response_affinities().record(\n            conversation_namespace,\n            &conversation_id,\n            owner,\n            destination,\n        ) {\n            return affinity_error(&error);\n        }\n    }\n    native_response(forwarded)\n}\n\npub async fn conversation(\n    State(state): State<AppState>,\n    Path(conversation_id): Path<String>,\n    OriginalUri(uri): OriginalUri,\n    request: Request,\n) -> Response {\n    let (claims, owner) = match authenticate(&state, request.headers()) {\n        Ok(authenticated) => authenticated,\n        Err(response) => return response,\n    };\n    let Some((conversation_namespace, item_namespace)) =\n        ResponseNamespace::conversations_from_path(uri.path())\n    else {\n        return conversation_not_found();\n    };\n    if conversation_namespace == ResponseNamespace::QwenConversations {\n        return unsupported();\n    }\n    let affinity = match lookup(\n        &state,\n        conversation_namespace,\n        &conversation_id,\n        &owner,\n        conversation_not_found,\n    ) {\n        Ok(affinity) => affinity,\n        Err(response) => return response,\n    };\n    if !matches!(\n        request.method(),\n        &Method::GET | &Method::PATCH | &Method::DELETE\n    ) {\n        return method_not_allowed();\n    }\n    let (parts, body) = request.into_parts();\n    let body = match bounded_request_body(&state, body).await {\n        Ok(body) => body,\n        Err(response) => return response,\n    };\n    let path = format!(\n        \"/v1/conversations/{}\",\n        crate::responses_lifecycle::percent_encode_segment(&conversation_id)\n    );\n    let forwarded = match forward(\n        &state,\n        &claims,\n        &parts.method,\n        &parts.headers,\n        &body,\n        uri.path(),\n        &with_query(&path, &uri),\n        &affinity.destination,\n    )\n    .await\n    {\n        Ok(forwarded) => forwarded,\n        Err(response) => return response,\n    };\n    if matches!(forwarded.status, StatusCode::NOT_FOUND | StatusCode::GONE) {\n        let _ = remove_conversation(&state, &affinity, item_namespace);\n        return conversation_not_found();\n    }\n    if parts.method == Method::DELETE\n        && forwarded.status.is_success()\n        && let Err(response) = remove_conversation(&state, &affinity, item_namespace)\n    {\n        return response;\n    }\n    native_response(forwarded)\n}\n\npub async fn items(\n    State(state): State<AppState>,\n    Path(conversation_id): Path<String>,\n    OriginalUri(uri): OriginalUri,\n    request: Request,\n) -> Response {\n    let (claims, owner) = match authenticate(&state, request.headers()) {\n        Ok(authenticated) => authenticated,\n        Err(response) => return response,\n    };\n    let Some((conversation_namespace, item_namespace)) =\n        ResponseNamespace::conversations_from_path(uri.path())\n    else {\n        return conversation_not_found();\n    };\n    if conversation_namespace == ResponseNamespace::QwenConversations {\n        return unsupported();\n    }\n    let affinity = match lookup(\n        &state,\n        conversation_namespace,\n        &conversation_id,\n        &owner,\n        conversation_not_found,\n    ) {\n        Ok(affinity) => affinity,\n        Err(response) => return response,\n    };\n    if !matches!(request.method(), &Method::GET | &Method::POST) {\n        return method_not_allowed();\n    }\n    let (parts, body) = request.into_parts();\n    let body = match bounded_request_body(&state, body).await {\n        Ok(body) => body,\n        Err(response) => return response,\n    };\n    let path = format!(\n        \"/v1/conversations/{}/items\",\n        crate::responses_lifecycle::percent_encode_segment(&conversation_id)\n    );\n    let forwarded = match forward(\n        &state,\n        &claims,\n        &parts.method,\n        &parts.headers,\n        &body,\n        uri.path(),\n        &with_query(&path, &uri),\n        &affinity.destination,\n    )\n    .await\n    {\n        Ok(forwarded) => forwarded,\n        Err(response) => return response,\n    };\n    if matches!(forwarded.status, StatusCode::NOT_FOUND | StatusCode::GONE) {\n        let _ = remove_conversation(&state, &affinity, item_namespace);\n        return conversation_not_found();\n    }\n    if forwarded.status.is_success() {\n        for item_id in list_ids(&forwarded.body) {\n            if let Err(error) = state.provider_store.response_affinities().record_child(\n                item_namespace,\n                &item_id,\n                &conversation_id,\n                owner.clone(),\n                affinity.destination.clone(),\n            ) {\n                return affinity_error(&error);\n            }\n        }\n    }\n    native_response(forwarded)\n}\n\npub async fn item(\n    State(state): State<AppState>,\n    Path((conversation_id, item_id)): Path<(String, String)>,\n    OriginalUri(uri): OriginalUri,\n    request: Request,\n) -> Response {\n    let (claims, owner) = match authenticate(&state, request.headers()) {\n        Ok(authenticated) => authenticated,\n        Err(response) => return response,\n    };\n    let Some((conversation_namespace, item_namespace)) =\n        ResponseNamespace::conversations_from_path(uri.path())\n    else {\n        return item_not_found();\n    };\n    if conversation_namespace == ResponseNamespace::QwenConversations {\n        return unsupported();\n    }\n    let conversation = match lookup(\n        &state,\n        conversation_namespace,\n        &conversation_id,\n        &owner,\n        conversation_not_found,\n    ) {\n        Ok(affinity) => affinity,\n        Err(response) => return response,\n    };\n    let item = match lookup(&state, item_namespace, &item_id, &owner, item_not_found) {\n        Ok(affinity)\n            if affinity.parent_id.as_deref() == Some(conversation_id.as_str())\n                && affinity.destination == conversation.destination =>\n        {\n            affinity\n        }\n        Ok(_) => return item_not_found(),\n        Err(response) => return response,\n    };\n    if !matches!(request.method(), &Method::GET | &Method::DELETE) {\n        return method_not_allowed();\n    }\n    let (parts, body) = request.into_parts();\n    let body = match bounded_request_body(&state, body).await {\n        Ok(body) => body,\n        Err(response) => return response,\n    };\n    let path = format!(\n        \"/v1/conversations/{}/items/{}\",\n        crate::responses_lifecycle::percent_encode_segment(&conversation_id),\n        crate::responses_lifecycle::percent_encode_segment(&item_id)\n    );\n    let forwarded = match forward(\n        &state,\n        &claims,\n        &parts.method,\n        &parts.headers,\n        &body,\n        uri.path(),\n        &with_query(&path, &uri),\n        &item.destination,\n    )\n    .await\n    {\n        Ok(forwarded) => forwarded,\n        Err(response) => return response,\n    };\n    if matches!(forwarded.status, StatusCode::NOT_FOUND | StatusCode::GONE) {\n        let _ = state\n            .provider_store\n            .response_affinities()\n            .remove_if_matches(&item);\n        return item_not_found();\n    }\n    if parts.method == Method::DELETE\n        && forwarded.status.is_success()\n        && let Err(error) = state\n            .provider_store\n            .response_affinities()\n            .remove_if_matches(&item)\n    {\n        return affinity_error(&error);\n    }\n    native_response(forwarded)\n}\n\nfn authenticate(\n    state: &AppState,\n    headers: &HeaderMap,\n) -> crate::translation_core::Outcome<(crate::token::TokenClaims, ResponseOwner), Response> {\n    let claims = crate::proxy::authenticate_client_error(state, headers)\n        .map_err(|error| error.render(crate::api_error::ApiDialect::OpenAi))?;\n    let owner = ResponseOwner::from_claims(&claims)\n        .map_err(|error| openai_error(StatusCode::FORBIDDEN, \"permission_error\", &error))?;\n    Ok((claims, owner))\n}\n\nconst fn destination_matches(\n    namespace: ResponseNamespace,\n    destination: &AffinityDestination,\n) -> bool {\n    matches!(\n        (namespace, destination),\n        (\n            ResponseNamespace::OpenAiConversations,\n            AffinityDestination::StoredProvider {\n                provider_kind: crate::providers::ProviderKind::OpenAICompatible,\n                ..\n            }\n        ) | (\n            ResponseNamespace::CodexConversations,\n            AffinityDestination::Subscription {\n                provider: crate::subscription::SubscriptionProvider::Codex,\n                ..\n            }\n        )\n    )\n}\n\nfn lookup(\n    state: &AppState,\n    namespace: ResponseNamespace,\n    id: &str,\n    owner: &ResponseOwner,\n    missing: fn() -> Response,\n) -> Result<ResponseAffinity, Response> {\n    match state\n        .provider_store\n        .response_affinities()\n        .lookup(namespace, id, owner)\n    {\n        Ok(Some(affinity)) => Ok(affinity),\n        Ok(None) => Err(missing()),\n        Err(error) => Err(affinity_error(&error)),\n    }\n}\n\n#[allow(clippy::too_many_arguments)]\nasync fn forward(\n    state: &AppState,\n    claims: &crate::token::TokenClaims,\n    method: &Method,\n    headers: &HeaderMap,\n    body: &Bytes,\n    client_path: &crate::translation_core::Str,\n    upstream_path: &crate::translation_core::Str,\n    destination: &AffinityDestination,\n) -> crate::translation_core::Outcome<Forwarded, Response> {\n    let correlation_id = crate::request_log::correlation_id(headers);\n    let (upstream, account) = match destination {\n        AffinityDestination::StoredProvider {\n            name,\n            provider_kind,\n            base_url,\n        } => (\n            crate::responses_lifecycle::forward_stored_provider(\n                state,\n                claims,\n                method,\n                headers,\n                body,\n                client_path,\n                upstream_path,\n                name,\n                *provider_kind,\n                base_url,\n                &correlation_id,\n            )\n            .await?,\n            None,\n        ),\n        AffinityDestination::Subscription {\n            provider,\n            account,\n            upstream_account_id,\n            base_url,\n        } => (\n            crate::responses_lifecycle::forward_subscription(\n                state,\n                claims,\n                method,\n                headers,\n                body,\n                client_path,\n                upstream_path,\n                *provider,\n                account,\n                upstream_account_id.as_deref(),\n                base_url,\n                &correlation_id,\n            )\n            .await?,\n            Some(account.as_str()),\n        ),\n    };\n    read_upstream(state, upstream, account, body.len() as u64, &correlation_id).await\n}\n\nasync fn read_upstream(\n    state: &AppState,\n    upstream: reqwest::Response,\n    account: crate::translation_core::Maybe<&crate::translation_core::Str>,\n    bytes_sent: u64,\n    correlation_id: &crate::translation_core::Str,\n) -> crate::translation_core::Outcome<Forwarded, Response> {\n    let status = StatusCode::from_u16(upstream.status().as_u16())\n        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);\n    let headers = crate::proxy::relay_response_headers(upstream.headers());\n    let mut stream = upstream.bytes_stream();\n    let mut body = Vec::new();\n    while let Some(chunk) = stream.next().await {\n        let chunk = chunk\n            .map_err(|error| upstream_error(&format!(\"upstream body read failed: {error}\")))?;\n        if body.len().saturating_add(chunk.len()) > state.max_proxy_request_bytes {\n            return Err(upstream_error(\"upstream response exceeds the proxy limit\"));\n        }\n        body.extend_from_slice(&chunk);\n    }\n    state\n        .request_log\n        .record_upstream_body(correlation_id, &body);\n    state.metrics.record_request(\n        crate::metrics::Surface::OpenAIResponses,\n        status.as_u16(),\n        account,\n    );\n    state.metrics.record_bytes(bytes_sent, body.len() as u64);\n    Ok(Forwarded {\n        status,\n        headers,\n        body: Bytes::from(body),\n    })\n}\n\nasync fn bounded_request_body(state: &AppState, body: Body) -> crate::translation_core::Outcome<Bytes, Response> {\n    axum::body::to_bytes(body, state.max_proxy_request_bytes)\n        .await\n        .map_err(|error| {\n            openai_error(\n                StatusCode::PAYLOAD_TOO_LARGE,\n                \"invalid_request_error\",\n                &format!(\"request body exceeds the proxy limit: {error}\"),\n            )\n        })\n}\n\nfn remove_conversation(\n    state: &AppState,\n    affinity: &ResponseAffinity,\n    item_namespace: ResponseNamespace,\n) -> crate::translation_core::Outcome<(), Response> {\n    let store = state.provider_store.response_affinities();\n    store\n        .remove_children(\n            item_namespace,\n            &affinity.response_id,\n            &affinity.owner,\n            &affinity.destination,\n        )\n        .map_err(|error| affinity_error(&error))?;\n    store\n        .remove_if_matches(affinity)\n        .map_err(|error| affinity_error(&error))?;\n    Ok(())\n}\n\nfn root_id(body: &[u8]) -> crate::translation_core::Maybe<String> {\n    serde_json::from_slice::<serde_json::Value>(body)\n        .ok()?\n        .get(\"id\")?\n        .as_str()\n        .filter(|id| !id.is_empty())\n        .map(str::to_string)\n}\n\nfn list_ids(body: &[u8]) -> Vec<String> {\n    serde_json::from_slice::<serde_json::Value>(body)\n        .ok()\n        .and_then(|value| {\n            value\n                .get(\"data\")\n                .and_then(crate::translation_core::Json::as_array)\n                .cloned()\n        })\n        .unwrap_or_default()\n        .into_iter()\n        .filter_map(|item| {\n            item.get(\"id\")\n                .and_then(crate::translation_core::Json::as_str)\n                .map(str::to_string)\n        })\n        .filter(|id| !id.is_empty())\n        .collect()\n}\n\nfn with_query(path: &crate::translation_core::Str, uri: &Uri) -> String {\n    uri.query()\n        .map_or_else(|| path.to_string(), |query| format!(\"{path}?{query}\"))\n}\n\nfn native_response(forwarded: Forwarded) -> Response {\n    let mut response = Response::new(Body::from(forwarded.body));\n    *response.status_mut() = forwarded.status;\n    *response.headers_mut() = forwarded.headers;\n    response\n}\n\nfn conversation_not_found() -> Response {\n    resource_not_found(\"Conversation\", \"conversation_not_found\")\n}\n\nfn item_not_found() -> Response {\n    resource_not_found(\"Conversation item\", \"conversation_item_not_found\")\n}\n\nfn resource_not_found(message: &crate::translation_core::Str, code: &crate::translation_core::Str) -> Response {\n    (\n        StatusCode::NOT_FOUND,\n        axum::Json(crate::translation_core::json!({\n            \"error\": {\n                \"message\": format!(\"{message} not found\"),\n                \"type\": \"invalid_request_error\",\n                \"param\": serde_json::Value::Null,\n                \"code\": code,\n            }\n        })),\n    )\n        .into_response()\n}\n\nfn unsupported() -> Response {\n    openai_error(\n        StatusCode::BAD_REQUEST,\n        \"invalid_request_error\",\n        \"the selected service does not support native Conversations resources\",\n    )\n}\n\nfn method_not_allowed() -> Response {\n    openai_error(\n        StatusCode::METHOD_NOT_ALLOWED,\n        \"invalid_request_error\",\n        \"the requested Conversations operation is not supported\",\n    )\n}\n\nfn affinity_error(error: &impl std::fmt::Display) -> Response {\n    openai_error(\n        StatusCode::SERVICE_UNAVAILABLE,\n        \"api_error\",\n        &format!(\"resource affinity is unavailable: {error}\"),\n    )\n}\n\nfn upstream_error(message: &crate::translation_core::Str) -> Response {\n    openai_error(StatusCode::BAD_GATEWAY, \"api_error\", message)\n}\n\nfn openai_error(status: StatusCode, error_type: &crate::translation_core::Str, message: &crate::translation_core::Str) -> Response {\n    crate::api_error::PresentedError {\n        status,\n        error_type,\n        message,\n    }\n    .render(crate::api_error::ApiDialect::OpenAi)\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn paths_encode_ids_as_single_segments_and_keep_queries() {\n        assert_eq!(\n            with_query(\n                \"/v1/conversations/conv.%3Fopaque/items\",\n                &\"/ignored?after=item_1&limit=20&order=desc\".parse().unwrap()\n            ),\n            \"/v1/conversations/conv.%3Fopaque/items?after=item_1&limit=20&order=desc\"\n        );\n    }\n}\n";

const ORIGINAL_LOG_ANALYSIS="//! Answer questions about the request log.\n//!\n//! The log is the router's only record of what actually happened, but it had to\n//! be read with `grep`/`jq` one-liners invented on the spot. That produced\n//! confident wrong answers in both directions (issue #234):\n//!\n//! - searching for `error|warn` found nothing and suggested the proxy was\n//!   uninvolved, because a stream dying mid-flight is logged at `INFO`;\n//! - counting streams without `message_stop` reported 100%, because the bodies\n//!   are compressed and the terminator cannot appear as a substring — the check\n//!   was structurally incapable of any other answer.\n//!\n//! An analyser that knows the log's own encoding and semantics cannot make\n//! either mistake, and says so explicitly when a body is undecodable rather\n//! than counting it as evidence.\n\nuse std::collections::BTreeMap;\nuse std::path::{Path, PathBuf};\n\nuse serde_json::{Value, json};\n\n/// One exchange, assembled from the records sharing a correlation id.\n#[derive(Debug, Default, Clone)]\n// Each flag is an independent fact the log either states or does not: whether\n// it streamed, whether that was established, whether a stream was asked for,\n// whether the frames were readable. They are not phases of one state machine,\n// and collapsing them into enums would hide that a log may answer some and\n// stay silent on others.\n#[allow(clippy::struct_excessive_bools)]\npub struct Exchange {\n    pub correlation_id: String,\n    pub status: Option<u64>,\n    pub upstream_status: Option<u64>,\n    pub uri: Option<String>,\n    /// Whether the response was actually streamed, decided from evidence.\n    ///\n    /// Every response is relayed through the same byte-stream machinery, so the\n    /// presence of body records says nothing about whether the exchange was a\n    /// stream. Deciding by default counted healthy non-streamed traffic as\n    /// streams with an unknown ending (issue #252).\n    pub streamed: bool,\n    /// Whether anything in the log actually settled the question either way.\n    pub stream_evidence: bool,\n    /// The response media type, when one was recorded.\n    pub response_media_type: Option<String>,\n    /// Whether the request asked for a stream, as a corroborating signal.\n    pub stream_requested: bool,\n    /// Whether a recorded body carried this dialect's terminating event.\n    ///\n    /// The relay writes a `stream_end` record only on the Anthropic path, so an\n    /// `OpenAI` or Gemini stream reaches the log without one and used to be\n    /// reported as ending in an unknown state — although the terminator was\n    /// sitting in the body the log had already captured (issue #258).\n    pub body_terminated: bool,\n    /// Whether the recorded frames could be read at all.\n    ///\n    /// A compressed stream is relayed and logged as the encoded bytes it was,\n    /// so scanning it for `message_stop` searches gzip and always fails.\n    /// Counting that as a missing terminator reported many completed streams\n    /// as failing (issue #255).\n    pub inspectable: bool,\n    /// From the terminal `stream_end` record, when one is present (issue #230).\n    pub stream_outcome: Option<String>,\n    pub stream_complete: Option<bool>,\n    pub frames: u64,\n    /// Bodies that could not be decoded, so nothing is inferred from them.\n    pub undecodable_bodies: u64,\n    pub records: u64,\n    /// Whether the decoded frames carry an SSE `error` event.\n    ///\n    /// A turn that failed mid-stream returns 200 at the transport layer, so\n    /// without reading the frames it is indistinguishable from one that\n    /// succeeded (issue #328).\n    pub stream_error: bool,\n    /// The encoded response frames, in the order they were recorded.\n    ///\n    /// Only their concatenation is a valid compressed stream, so they are kept\n    /// until the whole exchange has been read and decoded together (issue\n    /// #328).\n    encoded_frames: Vec<u8>,\n    /// The `content-encoding` the response declared, if it declared one.\n    content_encoding: Option<String>,\n}\n\nimpl Exchange {\n    /// Whether this exchange finished in a way the log can vouch for.\n    ///\n    /// Only a stream whose frames could be read can testify to a truncation.\n    #[must_use]\n    pub fn is_incomplete_stream(&self) -> bool {\n        self.streamed && self.inspectable && self.stream_complete == Some(false)\n    }\n\n    /// A turn that failed inside a stream the transport called successful.\n    #[must_use]\n    pub const fn carried_an_error(&self) -> bool {\n        self.stream_error\n    }\n\n    /// A stream whose frames were encoded, so the log cannot say how it ended.\n    ///\n    /// Reported as its own class rather than as a truncation: \"not verifiable\"\n    /// is honest, \"truncated\" is not (issue #255).\n    #[must_use]\n    pub const fn is_unverifiable_stream(&self) -> bool {\n        self.streamed && !self.inspectable\n    }\n\n    /// A streamed exchange with no terminal record at all: the router was\n    /// restarted mid-turn, or the relay never settled.\n    #[must_use]\n    pub const fn is_unterminated(&self) -> bool {\n        self.streamed && self.inspectable && self.stream_outcome.is_none() && !self.body_terminated\n    }\n}\n\n/// What one log directory contains.\n#[derive(Debug, Default)]\npub struct Summary {\n    pub exchanges: usize,\n    pub records: u64,\n    pub bytes: u64,\n    pub statuses: BTreeMap<u64, usize>,\n    pub streamed: usize,\n    /// Exchanges established as ordinary single-shot replies, reported so the\n    /// totals are readable at a glance rather than inferred by subtraction.\n    pub non_streamed: usize,\n    pub incomplete_streams: usize,\n    pub unterminated_streams: usize,\n    /// Streams whose frames were encoded, so how they ended is not knowable\n    /// from the log — reported apart from the ones that demonstrably failed.\n    pub unverifiable_streams: usize,\n    /// Records the analyser could not parse, stated rather than skipped.\n    pub unparsable_records: u64,\n    pub undecodable_bodies: u64,\n}\n\nimpl Summary {\n    #[must_use]\n    pub fn to_json(&self) -> crate::translation_core::Json {\n        json!({\n            \"exchanges\": self.exchanges,\n            \"records\": self.records,\n            \"bytes\": self.bytes,\n            \"streamed\": self.streamed,\n            \"non_streamed\": self.non_streamed,\n            \"incomplete_streams\": self.incomplete_streams,\n            \"unterminated_streams\": self.unterminated_streams,\n            \"unverifiable_streams\": self.unverifiable_streams,\n            \"unparsable_records\": self.unparsable_records,\n            \"undecodable_bodies\": self.undecodable_bodies,\n            \"statuses\": self\n                .statuses\n                .iter()\n                .map(|(status, count)| (status.to_string(), *count))\n                .collect::<BTreeMap<_, _>>(),\n        })\n    }\n\n    #[must_use]\n    pub fn render(&self) -> String {\n        use std::fmt::Write as _;\n        let mut out = String::new();\n        let _ = writeln!(\n            out,\n            \"exchanges {}  records {}  bytes {}\",\n            self.exchanges, self.records, self.bytes\n        );\n        let _ = writeln!(\n            out,\n            \"streamed {}  non-streamed {}  incomplete {}  no terminal record {}  \\\n             not verifiable {}\",\n            self.streamed,\n            self.non_streamed,\n            self.incomplete_streams,\n            self.unterminated_streams,\n            self.unverifiable_streams\n        );\n        if self.statuses.is_empty() {\n            out.push_str(\"statuses: none recorded\\n\");\n        } else {\n            let statuses = self\n                .statuses\n                .iter()\n                .map(|(status, count)| format!(\"{status}×{count}\"))\n                .collect::<Vec<_>>()\n                .join(\"  \");\n            let _ = writeln!(out, \"statuses: {statuses}\");\n        }\n        // Integrity is reported even when clean: silence about unreadable data\n        // is what produced the original false positive.\n        let _ = writeln!(\n            out,\n            \"integrity: {} unparsable record(s), {} undecodable body(ies)\",\n            self.unparsable_records, self.undecodable_bodies\n        );\n        out\n    }\n}\n\n/// A named anomaly, with the ids needed to inspect it.\n#[derive(Debug, Clone)]\npub struct Anomaly {\n    pub kind: &'static str,\n    pub detail: String,\n    pub correlation_ids: Vec<String>,\n}\n\n/// Read every request log under `root`, optionally for one token.\n///\n/// Returns the exchanges plus counts of what could not be read, so a caller\n/// never has to infer absence from silence.\npub fn read_exchanges(\n    root: &Path,\n    token: crate::translation_core::Maybe<&crate::translation_core::Str>,\n) -> std::io::Result<(Vec<Exchange>, u64, u64)> {\n    let mut by_id: BTreeMap<String, Exchange> = BTreeMap::new();\n    let mut unparsable = 0;\n    let mut bytes = 0;\n    for path in log_files(root, token)? {\n        let contents = std::fs::read_to_string(&path)?;\n        bytes += contents.len() as u64;\n        for line in contents.lines().filter(|line| !line.trim().is_empty()) {\n            // Either encoding: earlier releases wrote JSON Lines, and new\n            // records are links notation (issue #336).\n            let Some(record) = crate::lino_json::decode_line(line) else {\n                unparsable += 1;\n                continue;\n            };\n            absorb(&mut by_id, &record);\n        }\n    }\n    let exchanges = by_id\n        .into_values()\n        .map(|mut exchange| {\n            // Decode before classifying: the terminator the classification\n            // looks for is inside the bytes, and searching them encoded is\n            // what made every compressed stream unverifiable (issue #328).\n            settle_encoded_frames(&mut exchange);\n            resolve_stream_classification(&mut exchange);\n            exchange\n        })\n        .collect();\n    Ok((exchanges, unparsable, bytes))\n}\n\nfn log_files(root: &Path, token: crate::translation_core::Maybe<&crate::translation_core::Str>) -> std::io::Result<Vec<PathBuf>> {\n    let mut files = Vec::new();\n    if !root.is_dir() {\n        return Ok(files);\n    }\n    for entry in std::fs::read_dir(root)? {\n        let entry = entry?;\n        if !entry.path().is_dir() {\n            continue;\n        }\n        let name = entry.file_name().to_string_lossy().into_owned();\n        if token.is_some_and(|token| !name.starts_with(token)) {\n            continue;\n        }\n        // Either name. The log is renamed to `requests.lino` on its token's\n        // next write, so a token that has been idle since the rename still\n        // has readable history under the old one (issue #346).\n        let current = entry.path().join(\"requests.lino\");\n        let legacy = entry.path().join(\"requests.jsonl\");\n        if current.is_file() {\n            files.push(current);\n        }\n        if legacy.is_file() {\n            files.push(legacy);\n        }\n    }\n    files.sort();\n    Ok(files)\n}\n\nfn absorb(by_id: &mut BTreeMap<String, Exchange>, record: &Value) {\n    let Some(id) = record\n        .get(\"correlation_id\")\n        .and_then(Value::as_str)\n        .map(str::to_string)\n    else {\n        return;\n    };\n    let phase = record.get(\"phase\").and_then(Value::as_str).unwrap_or(\"\");\n    let exchange = by_id.entry(id.clone()).or_insert_with(|| Exchange {\n        correlation_id: id,\n        // Readable until the log says otherwise, so a log written before the\n        // encoding was recorded keeps exactly the meaning it had.\n        inspectable: true,\n        ..Exchange::default()\n    });\n    exchange.records += 1;\n    match phase {\n        \"client_request\" => {\n            if let Some(uri) = record.get(\"uri\").and_then(Value::as_str) {\n                exchange.uri = Some(uri.to_string());\n            }\n            // A body stored as base64 is compressed or binary; it is recorded\n            // as undecodable rather than searched for terminators (issue #231).\n            if record\n                .get(\"body\")\n                .is_some_and(|body| body.get(\"base64\").is_some())\n            {\n                exchange.undecodable_bodies += 1;\n            }\n            if request_asks_for_a_stream(record) {\n                exchange.stream_requested = true;\n            }\n        }\n        \"client_response\" => {\n            exchange.status = record.get(\"status\").and_then(Value::as_u64);\n            note_response_encoding(exchange, record);\n            note_response_content_type(exchange, record);\n        }\n        \"upstream_response\" => {\n            exchange.upstream_status = record.get(\"status\").and_then(Value::as_u64);\n            note_response_encoding(exchange, record);\n            note_response_content_type(exchange, record);\n        }\n        \"upstream_response_body\" | \"client_response_body\" => {\n            if phase == \"upstream_response_body\" {\n                exchange.frames += 1;\n            }\n            if let Some(encoded) = record\n                .get(\"body\")\n                .and_then(|body| body.get(\"base64\"))\n                .and_then(Value::as_str)\n            {\n                if phase == \"upstream_response_body\" {\n                    exchange.undecodable_bodies += 1;\n                    // Kept rather than counted and discarded: the bytes are\n                    // ordinary gzip or brotli, and only their concatenation\n                    // decodes (issue #328).\n                    if let Ok(bytes) =\n                        base64::Engine::decode(&base64::engine::general_purpose::STANDARD, encoded)\n                    {\n                        exchange.encoded_frames.extend_from_slice(&bytes);\n                    }\n                }\n            } else if let Some(body) = record.get(\"body\")\n                && body_carries_a_terminator(body)\n            {\n                exchange.body_terminated = true;\n            }\n        }\n        \"stream_end\" => {\n            // Not evidence of streaming on its own: the relay emits this record\n            // for every response, streamed or not, so believing it is what made\n            // a single-shot JSON reply look like a stream that never ended\n            // (issue #252). A recorded media type outranks it.\n            if !exchange.stream_evidence {\n                exchange.streamed = true;\n            }\n            exchange.stream_outcome = record\n                .get(\"outcome\")\n                .and_then(Value::as_str)\n                .map(str::to_string);\n            exchange.stream_complete = record.get(\"complete\").and_then(Value::as_bool);\n            // The relay knows whether it could read the frames, so a record\n            // that says so is believed over anything inferred from headers.\n            if let Some(inspectable) = record.get(\"inspectable\").and_then(Value::as_bool) {\n                exchange.inspectable = inspectable;\n            }\n            if let Some(frames) = record.get(\"frames\").and_then(Value::as_u64) {\n                exchange.frames = frames;\n            }\n        }\n        _ => {}\n    }\n}\n\n/// Note what a response's `content-type` says about whether it was streamed.\n///\n/// The response media type is the reliable marker: `text/event-stream` is a\n/// stream by definition, and any other concrete type — `application/json` for\n/// a single-shot reply — is not. Both the upstream and client response records\n/// carry it, and they agree in the ordinary case; either one is enough.\n///\n/// `Content-Encoding: gzip` is deliberately not consulted here. A compressed\n/// body arrives in several transfer chunks, and mistaking those for SSE frames\n/// is what produced a truncated-stream verdict — and a WARN — for every\n/// successful compressed reply (issue #252).\nfn note_response_content_type(exchange: &mut Exchange, record: &Value) {\n    let Some(content_type) = record\n        .get(\"headers\")\n        .and_then(|headers| headers.get(\"content-type\"))\n        .and_then(Value::as_str)\n    else {\n        return;\n    };\n    let media_type = content_type\n        .split(';')\n        .next()\n        .unwrap_or_default()\n        .trim()\n        .to_ascii_lowercase();\n    if media_type.is_empty() {\n        return;\n    }\n    exchange.response_media_type = Some(media_type.clone());\n    // Evidence either way is conclusive, so it overrides the request's\n    // `stream: true` hint: what the response actually was beats what was asked\n    // for, and a request may ask for a stream that the upstream answers whole.\n    exchange.streamed = media_type == \"text/event-stream\";\n    exchange.stream_evidence = true;\n}\n\n/// Whether decoded SSE carries an error event.\n///\n/// The transport says 200 and the stream carries the failure, so the status\n/// line cannot answer whether the turn succeeded — only the frames can.\nfn carries_a_stream_error(decoded: &crate::translation_core::Str) -> bool {\n    decoded.lines().any(|line| {\n        let line = line.trim();\n        line.eq_ignore_ascii_case(\"event: error\")\n            || line\n                .strip_prefix(\"data:\")\n                .and_then(|data| serde_json::from_str::<Value>(data.trim()).ok())\n                .and_then(|value| {\n                    value\n                        .get(\"type\")\n                        .and_then(crate::translation_core::Json::as_str)\n                        .map(|kind| kind == \"error\")\n                })\n                .unwrap_or(false)\n    })\n}\n\n/// Decode the response frames of one exchange as the single stream they are.\n///\n/// An operator reading a single exchange got base64 for every encoded body, so\n/// grepping the log for an error message, a model name or a prompt found\n/// nothing—not because the data was absent, but because it was unreadable as\n/// stored (issue #328).\n///\n/// The frames must be joined first: only the first carries the codec's header,\n/// so decoding them one at a time reads the opening frame and leaves the rest\n/// as base64 — which is most of the stream.\nfn decode_response_stream(\n    records: &[crate::translation_core::Json],\n    encoding: crate::translation_core::Maybe<crate::log_decode::Encoding>,\n) -> crate::translation_core::Maybe<String> {\n    let encoding = encoding?;\n    if encoding.is_identity() {\n        return None;\n    }\n    let mut joined = Vec::new();\n    for record in records {\n        if let Some(encoded) = stored_bytes(record)\n            && let Ok(bytes) =\n                base64::Engine::decode(&base64::engine::general_purpose::STANDARD, encoded)\n        {\n            joined.extend_from_slice(&bytes);\n        }\n    }\n    crate::log_decode::decode(&joined, encoding)\n}\n\n/// The base64 a record stores in place of a body, if it stores one.\nfn stored_bytes(record: &crate::translation_core::Json) -> crate::translation_core::Maybe<&crate::translation_core::Str> {\n    record\n        .get(\"body\")\n        .and_then(|body| body.get(crate::request_log::BINARY_BODY_KEY))\n        .and_then(crate::translation_core::Json::as_str)\n}\n\n/// Render the decoded stream against the first frame that carried it.\n///\n/// The decoded text belongs to the exchange rather than to any one frame, so\n/// it is shown once, where a reader looks for it, and the remaining frames say\n/// where it went instead of repeating an unreadable blob.\nfn render_decoded_body(\n    record: &mut Value,\n    index: usize,\n    first_body: usize,\n    decoded: Option<&String>,\n) {\n    let Some(decoded) = decoded else {\n        return;\n    };\n    if stored_bytes(record).is_none() {\n        return;\n    }\n    let rendered = if index == first_body {\n        Value::String(decoded.clone())\n    } else {\n        Value::String(String::from(\n            \"[decoded with the first frame: only the whole stream decodes]\",\n        ))\n    };\n    if let Some(body) = record.get_mut(\"body\") {\n        *body = rendered;\n    }\n}\n\n/// Record the response's declared content encoding.\n///\n/// Kept separate from the media type because a record may carry one without\n/// the other, and the encoding is what decides whether the frames can be read.\nfn note_response_encoding(exchange: &mut Exchange, record: &Value) {\n    if let Some(encoding) = record\n        .get(\"headers\")\n        .and_then(|headers| headers.get(\"content-encoding\"))\n        .and_then(Value::as_str)\n    {\n        exchange.content_encoding = Some(encoding.to_string());\n    }\n}\n\n/// Decide what the recorded frames say, decoding them when they are encoded.\n///\n/// `stream_not_verifiable` was a refusal to decompress, not a limit: the\n/// stored bytes are ordinary gzip or brotli and decode to readable SSE, yet\n/// compressed exchanges were declared unknowable. Only an encoding the router\n/// genuinely cannot decode is unverifiable now (issue #328).\nfn settle_encoded_frames(exchange: &mut Exchange) {\n    let encoding = exchange\n        .content_encoding\n        .as_deref()\n        .map_or(Some(crate::log_decode::Encoding::Identity), |declared| {\n            crate::log_decode::Encoding::parse(declared)\n        });\n    let Some(encoding) = encoding else {\n        // An encoding with no decoder: \"not knowable from the log\" is then the\n        // honest answer rather than an unattempted one.\n        exchange.inspectable = false;\n        return;\n    };\n    if encoding.is_identity() || exchange.encoded_frames.is_empty() {\n        return;\n    }\n    let Some(decoded) = crate::log_decode::decode(&exchange.encoded_frames, encoding) else {\n        // The bytes did not match what the header claimed. Nothing was read,\n        // so nothing is asserted about how the stream ended.\n        exchange.inspectable = false;\n        return;\n    };\n    exchange.inspectable = true;\n    exchange.undecodable_bodies = 0;\n    // An `error` event inside a 200 was invisible for the same reason the\n    // terminator was: it sits in a body nothing decoded. A failed turn was\n    // therefore indistinguishable from a successful one (issue #328).\n    if carries_a_stream_error(&decoded) {\n        exchange.stream_error = true;\n    }\n    if crate::request_log::text_terminates_stream(&decoded) {\n        exchange.body_terminated = true;\n        // The relay stamped `complete: false` because it declined to look, not\n        // because the stream was cut. A boolean meaning \"unchecked\" under the\n        // name \"incomplete\" is what produced the false negatives issue #234\n        // was filed about; the bytes now say otherwise, so they win.\n        if exchange.stream_complete == Some(false) {\n            exchange.stream_complete = Some(true);\n            exchange.stream_outcome = Some(String::from(\"completed\"));\n        }\n    }\n}\n\n/// Whether a recorded body carries a dialect's terminating event.\n///\n/// A body is stored as a JSON string when it decoded as UTF-8 and as a JSON\n/// document when it parsed as one; both are searched as text, since the marker\n/// is a substring either way. A base64 body is compressed or binary and is\n/// handled by `inspectable` instead (issue #255).\nfn body_carries_a_terminator(body: &crate::translation_core::Json) -> bool {\n    match body {\n        crate::translation_core::Json::String(text) => crate::request_log::text_terminates_stream(text),\n        crate::translation_core::Json::Null => false,\n        // A parsed document: search its rendered form, so a terminator that\n        // arrived as structured JSON is found too.\n        other => crate::request_log::text_terminates_stream(&other.to_string()),\n    }\n}\n\n/// Whether a request body asks for a streamed reply.\n///\n/// The Anthropic and `OpenAI` chat dialects both spell this `\"stream\": true`.\n/// This corroborates rather than decides: it is used only when no response\n/// media type was recorded, since a request can ask for a stream and receive a\n/// single-shot answer.\nfn request_asks_for_a_stream(record: &crate::translation_core::Json) -> bool {\n    record\n        .get(\"body\")\n        .and_then(|body| body.get(\"json\"))\n        .and_then(|body| body.get(\"stream\"))\n        .and_then(crate::translation_core::Json::as_bool)\n        .unwrap_or(false)\n}\n\n/// Settle the streamed question for exchanges the response never answered.\n///\n/// Called once the whole exchange is assembled, since the request record is\n/// read before the response that outranks it.\nconst fn resolve_stream_classification(exchange: &mut Exchange) {\n    if !exchange.stream_evidence && exchange.stream_requested {\n        exchange.streamed = true;\n    }\n}\n\n/// Summarise a set of exchanges.\n#[must_use]\npub fn summarise(exchanges: &[Exchange], unparsable: u64, bytes: u64) -> Summary {\n    let mut summary = Summary {\n        exchanges: exchanges.len(),\n        bytes,\n        unparsable_records: unparsable,\n        ..Summary::default()\n    };\n    for exchange in exchanges {\n        summary.records += exchange.records;\n        summary.undecodable_bodies += exchange.undecodable_bodies;\n        if let Some(status) = exchange.status.or(exchange.upstream_status) {\n            *summary.statuses.entry(status).or_default() += 1;\n        }\n        if exchange.streamed {\n            summary.streamed += 1;\n            if exchange.is_incomplete_stream() {\n                summary.incomplete_streams += 1;\n            }\n            if exchange.is_unterminated() {\n                summary.unterminated_streams += 1;\n            }\n            if exchange.is_unverifiable_stream() {\n                summary.unverifiable_streams += 1;\n            }\n        } else {\n            summary.non_streamed += 1;\n        }\n    }\n    summary\n}\n\n/// Name the anomalies in a set of exchanges.\n#[must_use]\npub fn anomalies(exchanges: &[Exchange]) -> Vec<Anomaly> {\n    let mut found = Vec::new();\n    let collect = |predicate: &dyn Fn(&Exchange) -> bool| {\n        exchanges\n            .iter()\n            .filter(|exchange| predicate(exchange))\n            .map(|exchange| exchange.correlation_id.clone())\n            .collect::<Vec<_>>()\n    };\n\n    let cut = collect(&Exchange::is_incomplete_stream);\n    if !cut.is_empty() {\n        found.push(Anomaly {\n            kind: \"stream_ended_without_terminator\",\n            detail: \"a streamed turn stopped before its dialect terminator; the client saw a \\\n                     truncated answer while the status line said 200\"\n                .to_string(),\n            correlation_ids: cut,\n        });\n    }\n\n    let unterminated = collect(&Exchange::is_unterminated);\n    if !unterminated.is_empty() {\n        found.push(Anomaly {\n            kind: \"no_terminal_record\",\n            detail: \"a streamed exchange has no terminal record, so how it ended is unknown\"\n                .to_string(),\n            correlation_ids: unterminated,\n        });\n    }\n\n    // Reported so the figure is visible, but worded as the absence of evidence\n    // it is: calling a healthy compressed stream truncated is what made the\n    // signal unusable (issue #255).\n    let errored = collect(&Exchange::carried_an_error);\n    if !errored.is_empty() {\n        found.push(Anomaly {\n            kind: \"stream_carried_an_error\",\n            detail: \"a streamed turn carried an error event while the status line said 200, \\\n                     so the transport reported success for a turn that failed\"\n                .to_string(),\n            correlation_ids: errored,\n        });\n    }\n    let unverifiable = collect(&Exchange::is_unverifiable_stream);\n    if !unverifiable.is_empty() {\n        found.push(Anomaly {\n            kind: \"stream_not_verifiable\",\n            detail: \"a streamed exchange was relayed under an encoding this router cannot \\\n                     decode, so its frames cannot be inspected for a terminator; how it \\\n                     ended is not knowable from the log\"\n                .to_string(),\n            correlation_ids: unverifiable,\n        });\n    }\n\n    let refused = collect(&|exchange| matches!(exchange.status, Some(401 | 403)));\n    if refused.len() > 1 {\n        found.push(Anomaly {\n            kind: \"repeated_authentication_failure\",\n            detail: format!(\n                \"{} exchanges were refused with 401/403, which is misconfiguration rather \\\n                 than load\",\n                refused.len()\n            ),\n            correlation_ids: refused,\n        });\n    }\n\n    let throttled = collect(&|exchange| exchange.status == Some(429));\n    if !throttled.is_empty() {\n        found.push(Anomaly {\n            kind: \"rate_limited\",\n            detail: format!(\"{} exchanges were rate limited\", throttled.len()),\n            correlation_ids: throttled,\n        });\n    }\n\n    let undecodable = collect(&|exchange| exchange.undecodable_bodies > 0);\n    if !undecodable.is_empty() {\n        found.push(Anomaly {\n            kind: \"undecodable_bodies\",\n            detail: \"bodies are compressed or binary, so their contents cannot be inspected \\\n                     from the log; recorded so absence of evidence is not read as evidence\"\n                .to_string(),\n            correlation_ids: undecodable,\n        });\n    }\n\n    found\n}\n\n/// Render one exchange's records in order.\npub fn show_records(\n    root: &Path,\n    token: crate::translation_core::Maybe<&crate::translation_core::Str>,\n    correlation_id: &crate::translation_core::Str,\n) -> std::io::Result<Vec<crate::translation_core::Json>> {\n    let mut out = Vec::new();\n    for path in log_files(root, token)? {\n        // The encoding is declared on the response record, which may arrive\n        // after the bodies it describes, so the whole exchange is read before\n        // anything is rendered.\n        let contents = std::fs::read_to_string(&path)?;\n        let records = contents\n            .lines()\n            .filter_map(crate::lino_json::decode_line)\n            .filter(|record| {\n                record.get(\"correlation_id\").and_then(crate::translation_core::Json::as_str) == Some(correlation_id)\n            })\n            .collect::<Vec<_>>();\n        let encoding = records\n            .iter()\n            .find_map(|record| {\n                record\n                    .get(\"headers\")\n                    .and_then(|headers| headers.get(\"content-encoding\"))\n                    .and_then(crate::translation_core::Json::as_str)\n            })\n            .map_or(Some(crate::log_decode::Encoding::Identity), |declared| {\n                crate::log_decode::Encoding::parse(declared)\n            });\n        let decoded = decode_response_stream(&records, encoding);\n        // The decoded text belongs to the whole stream, so it is rendered\n        // against the first frame that carried any of it.\n        let first_body = records\n            .iter()\n            .position(|record| stored_bytes(record).is_some())\n            .unwrap_or_default();\n        for (index, mut record) in records.into_iter().enumerate() {\n            render_decoded_body(&mut record, index, first_body, decoded.as_ref());\n            out.push(record);\n        }\n    }\n    Ok(out)\n}\n\n/// Render one exchange using the same decoded records as the operation API.\npub fn show(root: &Path, token: crate::translation_core::Maybe<&crate::translation_core::Str>, correlation_id: &crate::translation_core::Str) -> std::io::Result<String> {\n    let records = show_records(root, token, correlation_id)?;\n    crate::operation_output::report(crate::operation_reports::LogRecordsReport {\n        correlation_id: correlation_id.into(),\n        records: records.clone(),\n        output: Vec::new(),\n    });\n    if records.is_empty() {\n        return Ok(format!(\"no records for correlation id {correlation_id}\\n\"));\n    }\n    let mut rendered = String::new();\n    for record in records {\n        rendered.push_str(&serde_json::to_string_pretty(&record).unwrap_or_default());\n        rendered.push('\\n');\n    }\n    Ok(rendered)\n}\n\n#[cfg(test)]\n#[path = \"log_analysis_tests.rs\"]\nmod tests;\n\n#[cfg(test)]\n#[path = \"log_analysis_decode_tests.rs\"]\nmod decode_tests;\n";

const ORIGINAL_MANAGED_CATALOG="//! Model discovery and ordinary-token validation for wrapped clients.\n\nuse serde_json::Value;\n\nuse super::AnyError;\nuse crate::clients::{ClientKind, RouterModel};\n\npub(super) async fn fetch_models(\n    http: &reqwest::Client,\n    client: ClientKind,\n    base_url: &str,\n    token: &str,\n) -> Result<Vec<RouterModel>, AnyError> {\n    let url = format!(\"{base_url}{}\", client_models_path(client));\n    let request = http\n        .get(&url)\n        .header(\"x-link-assistant-client\", client.canonical_name());\n    let request = match client {\n        ClientKind::ClaudeCode => request.header(\"x-api-key\", token),\n        ClientKind::GeminiCli => request.header(\"x-goog-api-key\", token),\n        _ => request.bearer_auth(token),\n    };\n    let response = request\n        .send()\n        .await\n        .map_err(|error| format!(\"router token validation could not reach {url}: {error}\"))?;\n    let status = response.status();\n    let body = response.text().await.unwrap_or_default();\n    if status.is_success() {\n        let value: Value = serde_json::from_str(&body)\n            .map_err(|error| format!(\"router model catalog returned invalid JSON: {error}\"))?;\n        let rows = value\n            .get(\"data\")\n            .and_then(Value::as_array)\n            .ok_or(\"router model catalog did not contain a data array\")?;\n        let models: Vec<RouterModel> = crate::clients::parse_router_models(rows)?\n            .into_iter()\n            .filter(|model| !model.id.trim().is_empty())\n            .collect();\n        if models.is_empty() {\n            return Err(\n                \"router catalog contains no models authorized for this client token\".into(),\n            );\n        }\n        return Ok(models);\n    }\n    if status.as_u16() == 401 || status.as_u16() == 403 {\n        return Err(format!(\n            \"router rejected the supplied token as {} ({status})\",\n            token_rejection_reason(&body)\n        )\n        .into());\n    }\n    Err(format!(\n        \"router token validation failed at {url} ({status}): {}\",\n        crate::logging::http_failure(status.as_u16())\n    )\n    .into())\n}\n\npub(super) fn client_models_path(_client: ClientKind) -> &'static str {\n    use crate::route_contract::{RouteId, route_template};\n    route_template(RouteId::AggregateModels)\n}\n\nfn token_rejection_reason(body: &str) -> &'static str {\n    let message = serde_json::from_str::<Value>(body)\n        .ok()\n        .and_then(|value| {\n            value\n                .pointer(\"/error/message\")\n                .or_else(|| value.get(\"message\"))\n                .and_then(Value::as_str)\n                .map(str::to_ascii_lowercase)\n        })\n        .unwrap_or_else(|| body.to_ascii_lowercase());\n    if message.contains(\"expired\") {\n        \"expired\"\n    } else if message.contains(\"revoked\") {\n        \"revoked\"\n    } else {\n        \"invalid\"\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use crate::clients::ClientKind;\n\n    #[test]\n    fn wrapped_clients_use_the_client_scoped_normalized_catalog() {\n        assert_eq!(client_models_path(ClientKind::ClaudeCode), \"/api/models\");\n        assert_eq!(client_models_path(ClientKind::Codex), \"/api/models\");\n        assert_eq!(client_models_path(ClientKind::GeminiCli), \"/api/models\");\n        assert_eq!(client_models_path(ClientKind::QwenCode), \"/api/models\");\n        assert_eq!(client_models_path(ClientKind::Opencode), \"/api/models\");\n    }\n}\n";
